 Handler h=new Handler(Looper.getMainLooper());Dash view;Map<String,String> data=new HashMap<>(),last=new HashMap<>();ArrayList<Long> laps=new ArrayList<>();String url,ps5,track,car,lastLap="";boolean running;long lastPacket=0;float maxSpeed=0,fuelStart=Float.NaN,fuelLast=Float.NaN,fuelPerLap=Float.NaN;int packets=0;
