 Map<String,String> parse(String b)throws Exception{Map<String,String> out=new HashMap<>();if(b==null)return out;String s=b.trim();int a=s.indexOf('{'),z=s.lastIndexOf('}');if(a>=0&&z>a)s=s.substring(a,z+1);Object root=new JSONTokener(s).nextValue();flat(out,"",root);return out;}void flat(Map<String,String> out,String pre,Object x)throws Exception{if(x instanceof JSONObject){JSONObject j=(JSONObject)x;Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();Object v=j.get(k);String p=pre.length()==0?k:pre+"."+k;flat(out,p,v);if(v instanceof JSONObject&&(k.equals("fields")||k.equals("telemetry")||k.equals("position")||k.equals("car")))flat(out,"",v);}}else out.put(pre,String.valueOf(x));}
