 float speed(){return num("speed_kmh","speedKmh","velocityKmh","velocidade","kmh","speed");}float rpm(){return num("engine_rpm","EngineRPM","engineRPM","rpm","currentRpm");}float fuel(){return num("fuelPercent","fuel_percent","combustivelPorcentagem","fuelPercentage");}String speedT(){float s=speed();return Float.isNaN(s)?"--":String.valueOf(Math.round(s));}String maxT(){return maxSpeed<=0?"--":String.valueOf(Math.round(maxSpeed));}String gear(){return val("gear","marcha","currentGear","gears");}String best(){return val("bestLaptime","bestLap","best_lap","best_lap_text","melhorVolta");}String lap(){return val("lastLaptime","lastLap","last_lap","last_lap_text","ultimaVolta");}String currentLap(){return val("currentLapTime","current_lap_text","voltaAtualTempo");}String lapNo(){return val("voltasCorrigidas","correctedLaps","lapCount","completed_laps","lap","currentLap");}float throttle(){return num("throttle","throttleFiltered","throttle_percent","acelerador");}float brake(){return num("brake","brakeFiltered","brake_percent","freio");}float coolant(){return num("coolantTemp","coolant","waterTemp","water_temp");}float oil(){return num("oilTemp","oil_temp");}float boost(){return num("turbo","boostPressure","boost","manifoldPressure");}float g1(){return num("gForceLat","g_lat","lateralG","gForceX");}float g2(){return num("gForceLong","g_long","longitudinalG","gForceY");}
 void calc(){float s=speed(),f=fuel();if(!Float.isNaN(s)&&s>maxSpeed)maxSpeed=s;if(!Float.isNaN(f)){if(Float.isNaN(fuelStart))fuelStart=f;fuelLast=f;}String l=lap();if(!l.equals("--")&&!l.equals(lastLap)){long ms=toMs(l);if(ms>0){laps.add(ms);if(!Float.isNaN(fuelStart)&&!Float.isNaN(fuelLast))fuelPerLap=Math.max(0,fuelStart-fuelLast)/Math.max(1,laps.size());saveLap(l,false);}lastLap=l;}String t=val("trackName","track","pista","course","circuit");if(!t.equals("--"))track=t;String c=val("carName","car","model","modelo");if(!c.equals("--"))car=c;}
 long total(){long t=0;for(Long l:laps)t+=l;long e=toMs(val("totalTime","raceTime","tempoTotal","sessionTime"));return Math.max(t,e);}long toMs(String r){try{if(!valid(r))return 0;String s=r.trim().replace(',','.');if(!s.contains(":")){float n=Float.parseFloat(s);return n>1000?Math.round(n):Math.round(n*1000f);}String[] p=s.split(":");float sec=Float.parseFloat(p[p.length-1]);long m=p.length>=2?Long.parseLong(p[p.length-2]):0,hr=p.length>=3?Long.parseLong(p[p.length-3]):0;return hr*3600000L+m*60000L+Math.round(sec*1000f);}catch(Exception e){return 0;}}String fmt(long ms){if(ms<=0)return "--:--.---";long h=ms/3600000L;ms%=3600000L;long m=ms/60000L;ms%=60000L;long s=ms/1000L,z=ms%1000L;return h>0?String.format(Locale.US,"%02d:%02d:%02d.%03d",h,m,s,z):String.format(Locale.US,"%02d:%02d.%03d",m,s,z);}String one(float n){return Float.isNaN(n)?"--":String.format(Locale.US,"%.1f",n);}String pct(float n){return Float.isNaN(n)?"--":String.valueOf(Math.round(n));}String fuelT(){float f=fuel();return Float.isNaN(f)?"--":Math.round(f)+"%";}String autonomy(){return Float.isNaN(fuelLast)||Float.isNaN(fuelPerLap)||fuelPerLap<=0.05f?"--":String.format(Locale.US,"%.1f",fuelLast/fuelPerLap);}
 JSONArray sessions(){try{return new JSONArray(getSharedPreferences(P,0).getString(SES,"[]"));}catch(Exception e){return new JSONArray();}}void saveLap(String l,boolean manual){try{JSONArray a=sessions();JSONObject o=new JSONObject();o.put("date",new SimpleDateFormat("dd/MM/yyyy HH:mm",Locale.getDefault()).format(new Date()));o.put("session",manual?"manual":"auto_lap");o.put("track",track.length()==0?"Pista nao identificada":track);o.put("car",car);o.put("lap",l);o.put("best",best());o.put("total",fmt(total()));o.put("maxSpeedSession",Math.round(maxSpeed));o.put("maxSpeed",Math.round(maxSpeed));o.put("fuel",fuelT());a.put(o);getSharedPreferences(P,0).edit().putString(SES,a.toString()).apply();}catch(Exception e){}}
